referenceSolutions.python:
def recursiveShelvesBossReceipt(readings, k):
    a=readings
    out=[]
    def visit(left,right):
        if left>=right: return
        out.append(sum(a[left:right]))
        if right-left>1:
            mid=(left+right)//2
            visit(left,mid)
            visit(mid,right)
    visit(0,len(a))
    return sum((i+1)*x for i,x in enumerate(out))

